'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={jobs:[],sources:[],profile:{},history:[],autofill_history:[],questions:[],notifications:[],runs:[],settings:{scheduler_enabled:false,threshold:55},mode:'offline'},page='matches',query='',scope='preferred',category='all',onlyStrong=false,relevantOnly=true,selectedLane='all',laneUpload=null,demo=false,upload=null,lastFocus=null,notificationEnabled=false,seenNotifications=new Set(),pending=false;
const labels={matches:'Job matches',saved:'Saved jobs',applications:'Application history',questions:'Questions to answer once',notifications:'Notifications',sources:'Company coverage',settings:'Automation & setup',lanes:'Resumes & role lanes'};
const timeAgo=t=>{if(!t)return 'Never checked';const m=Math.max(0,Math.floor((Date.now()-new Date(t))/60000));return m<1?'Just now':m<60?`${m}m ago`:m<1440?`${Math.floor(m/60)}h ago`:`${Math.floor(m/1440)}d ago`};
const live=()=>data.mode==='live'&&!demo;
const statusLabel=s=>({saved:'Saved',opened:'Application opened',autofilled:'Autofilled · review remaining',needs_review:'Needs an answer',awaiting_captcha:'Waiting for your CAPTCHA check',in_progress:'Autopilot in progress',submission_attempted:'Submission attempted · unconfirmed',submitted:'Employer confirmation detected',failed:'Attempt failed',applied:'Applied · marked by you',dismissed:'Dismissed'}[s]||s);
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTime);window.toastTime=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
async function api(path,value){if(['/api/lane','/api/delete-lane','/api/automation/run'].includes(path)&&live()&&Number(data.backend_version)<4)throw Error('Restart Role Radar to load resume lanes and the application agent, then refresh this page.');if(!live())throw Error('Start the local server to use this feature. See Automation & setup.');if(['/api/profile','/api/question-answer'].includes(path)&&Number(data.backend_version)<3)throw Error('Restart Role Radar to load the new profile and autopilot backend, then refresh this page.');const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});let result;try{result=await r.json()}catch{throw Error('The backend did not return JSON.')}if(!r.ok)throw Error(result.error||'Request failed');return result}
async function refresh(initial=false){if(demo)return;try{const r=await fetch('/api/bootstrap',{cache:'no-store'});if(!r.ok)throw Error();const next=await r.json();if(next.mode!=='live')throw Error();data=next;if(notificationEnabled&&document.visibilityState==='hidden')for(const n of data.notifications.filter(n=>!n.seen&&!seenNotifications.has(n.id))){new Notification('New job match',{body:`${n.title} · relevance ${n.score}/100`,tag:String(n.id)}).onclick=()=>window.open(n.url,'_blank','noopener');seenNotifications.add(n.id)}for(const n of data.notifications)seenNotifications.add(n.id);updateChrome();if(initial||pending||($('#modal').hidden&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))){render();pending=false}}catch{if(initial){data.mode='offline';updateChrome();render()}}}
function updateChrome(){const ready=live();$('#connection').className='connection'+(ready?' online':'');$('#connection').innerHTML=`<i></i>${demo?'Illustrative preview':ready?'Local server connected':'Backend not connected'}`;$('#profile-name').textContent=data.profile.name||'Your profile';document.querySelectorAll('.avatar').forEach(x=>x.textContent=(data.profile.name||'Y')[0].toUpperCase());$('#match-count').textContent=data.jobs.filter(j=>j.match?.relevant!==false).length;$('#saved-count').textContent=data.history.filter(h=>h.status==='saved').length;$('#inbox-count').style.display=data.notifications.some(n=>!n.seen)?'block':'none';$('#example-toggle').textContent=demo?'Exit illustrative preview':'Preview illustrative examples'}
function title(eyebrow,heading,desc,buttons=''){return `<section class="page-title"><div><span class="eyebrow">${eyebrow}</span><h1>${heading}</h1><p>${desc}</p></div>${buttons}</section>`}
function disconnected(){return !live()?`<div class="notice ${demo?'':'error'}">${demo?'Illustrative preview: all example employers, jobs, relevance scores, and descriptions are fictional. No application can be sent.':'The backend is not connected. Start <code>python3 server.py</code> and open <a href="http://127.0.0.1:8877">http://127.0.0.1:8877</a> for resume processing, live collection, and saved history.'}</div>`:''}
function stat(label,value,caption,icon){return `<div class="stat"><div><span class="stat-label">${label}</span><b>${esc(value)}</b><small>${caption}</small></div><span class="stat-icon">${icon}</span></div>`}
function priorityPanel(){return `<div class="panel right-panel"><h3>Your search, in the right order</h3><div class="priority-step"><span class="step-num">1</span><div><b>Remote roles open from India</b><small>Country-restricted remote roles are grouped with worldwide jobs</small></div></div><div class="priority-step"><span class="step-num">2</span><div><b>Based in India</b><small>All cities. All company stages.</small></div></div><div class="priority-step"><span class="step-num">3</span><div><b>The rest of the world</b><small>Worldwide, as a third priority</small></div></div><div class="divider"></div><p class="tiny" style="margin-bottom:0">Resume relevance sorts jobs within each group. Work authorisation and seniority still need a review.</p></div>`}
function coveragePanel(){const verified=data.sources.filter(s=>s.last_success).length,total=data.sources.length;return `<div class="panel right-panel"><h3>A wider net. An honest view.</h3><p class="tiny">From early teams to global companies. Coverage expands with your company registry.</p>${['greenhouse','lever','ashby','smartrecruiters','career_page'].map(k=>`<div class="source-line"><span>${{greenhouse:'Greenhouse',lever:'Lever',ashby:'Ashby',smartrecruiters:'SmartRecruiters',career_page:'Company career pages'}[k]}</span><b>${data.sources.filter(s=>s.kind===k).length} sources</b></div>`).join('')}<div class="coverage-track"><span style="width:${total?verified/total*100:0}%"></span></div><p class="tiny" style="font-size:9px;margin:8px 0 12px">${verified} of ${total} sources fetched successfully at least once.</p><a class="button ghost" href="#sources">Explore company coverage →</a><div class="sync-banner"><b>◷ Twice daily, while your server runs</b><p>${data.collecting?'Collection in progress.':data.runs[0]?`Last attempt ${timeAgo(data.runs[0].started)}.`:'No collection has run here yet.'} Failed sources retry with backoff.</p></div></div>`}
function resumePanel(){const lanes=roleLanes().filter(l=>l.enabled!==false);return `<div class="panel right-panel"><span class="eyebrow">${hasResume()?'Your search directions':'Start with you'}</span><h3 style="font-family:Georgia,serif;font-size:20px;font-weight:400;margin:10px 0">${hasResume()?'The right resume for the right role.':'Your experience is the starting point.'}</h3><p class="tiny">${lanes.length?`${lanes.length} enabled role lane${lanes.length===1?'':'s'}. Each job is matched against the most suitable resume.`:hasResume()?'Your saved profile is used until you add focused role resumes.':'Add role-specific resumes to see suitable jobs and explainable match reasons.'}</p><a class="button secondary small" href="#lanes">${hasResume()?'Manage role resumes':'Add a role resume'} ↑</a></div>`}

function roleLanes(){return Array.isArray(data.lanes)?data.lanes:Array.isArray(data.profile.lanes)?data.profile.lanes:[]}
function hasResume(){return Boolean(data.profile.resume||roleLanes().some(l=>l.enabled!==false&&l.resume))}
function laneMatch(job){if(selectedLane==='all')return job.match;return (job.match.lane_matches||[]).find(m=>m.lane_id===selectedLane)||null}
function filteredJobs(){return data.jobs.map(job=>{const match=laneMatch(job);return match?{...job,match,_autopilot_match:job.match}:null}).filter(j=>j&&(page!=='saved'||data.history.some(h=>h.job_id===j.id&&h.status==='saved'))&&(!relevantOnly||page==='saved'||j.match.relevant!==false)&&(!query||(`${j.company} ${j.title} ${j.location} ${j.description}`).toLowerCase().includes(query.toLowerCase()))&&(scope==='all'||(scope==='preferred'?j.priority<=1:scope==='remote'?j.priority===0:scope==='india'?j.priority===1:j.priority===2))&&(category==='all'||j.category===category)&&(!onlyStrong||(j.match.score??0)>=data.settings.threshold)).sort((a,b)=>(a.priority??2)-(b.priority??2)||(b.match.score??-1)-(a.match.score??-1))}
function laneSelector(){return `<div class="lane-filter"><label for="match-lane">Preview role lane</label><select id="match-lane"><option value="all">Best fit across enabled resumes</option>${roleLanes().map(l=>`<option value="${esc(l.id)}" ${selectedLane===l.id?'selected':''}>${esc(l.name)}${l.enabled===false?' · paused':''}</option>`).join('')}</select><a href="#lanes">Manage resumes →</a><small>Autopilot chooses the best matching enabled resume for each job.</small></div>`}

function jobCard(j){const saved=data.history.some(h=>h.job_id===j.id&&h.status==='saved'),score=j.match.score;return `<article class="job-card"><span class="company-logo">${esc(j.company.slice(0,1))}</span><div class="job-body"><div class="company-line">${esc(j.company)} <span class="tag ${j.category==='MNC'?'blue':''}">${esc(j.category)}</span>${j.remote?'<span class="tag green">Remote</span>':''}</div><span class="match-score">${score===null?'Add resume':`${score}/100 relevance`}</span><h3><button class="job-title" data-action="detail" data-id="${j.id}">${esc(j.title)}</button></h3><div class="job-meta"><span>⌖ ${esc(j.location)}</span><span>◷ ${esc(j.employment||'Not specified')}</span>${j.salary?`<span class="salary">${esc(j.salary.slice(0,90))}</span>`:''}</div>${j.match.lane_name?`<div class="job-lane">◈ ${esc(j._autopilot_match?.lane_name||j.match.lane_name)} <span>${selectedLane!=='all'?`Preview: ${esc(j.match.lane_name)}`:j.match.relevant===false?'Outside your role criteria':'Selected resume'}</span></div>`:''}<div class="job-skills">${j.match.matched.slice(0,5).map(s=>`<span class="skill">${esc(s)}</span>`).join('')}${!j.match.matched.length?'<span class="skill">Open role to review requirements</span>':''}</div><div class="job-bottom"><small>${demo?'Fictional example':`Last seen ${timeAgo(j.last_seen)}`}<br>${esc(j.application_status?statusLabel(j.application_status):'Direct employer application')}</small><div class="job-buttons"><button class="save-button ${saved?'saved':''}" data-action="save" data-id="${j.id}" aria-label="${saved?'Unsave':'Save'} ${esc(j.title)}">${saved?'▣':'▱'}</button><button class="button secondary small" data-action="detail" data-id="${j.id}">View role ↗</button></div></div></div></article>`}
function matches(){const jobs=filteredJobs(),unread=data.notifications.filter(n=>!n.seen).length;return title('YOUR SEARCH, WORKING FOR YOU',page==='saved'?'A few worth keeping.':'Your next chapter starts here.',page==='saved'?'Come back to the roles that caught your attention.':'Less searching. More possibilities that look like you.',`<a class="button" href="#lanes"><span>↑</span> ${hasResume()?'Manage resumes':'Add role resume'}</a>`)+disconnected()+(data.jobs_truncated?`<div class="notice">Showing the top ${data.jobs.length} of ${data.job_total} active openings, ordered by remote roles available from India, India-based roles, then other locations. This keeps the local dashboard responsive.</div>`:'')+(!hasResume()?`<section class="onboarding-banner"><div><span class="eyebrow">A LITTLE CONTEXT GOES A LONG WAY</span><h2>Bring your experience.<br>We’ll help find the fit.</h2><p>Upload a resume to rank opportunities, see the reasons behind each match, and prepare application forms.</p></div><div class="banner-art"><div class="paper"><b></b><i></i><i></i><i></i><i></i></div><div class="check-circle">✓</div></div><button class="button" data-action="resume">Add your resume <span>↑</span></button></section>`:'')+`<div class="stat-row">${stat('Opportunities collected',data.job_total??data.jobs.length,'From your configured sources','◈')}${stat('Strong matches',data.jobs.filter(j=>(j.match.score??-1)>=data.settings.threshold).length,`Relevance ≥ ${data.settings.threshold}/100 in this view`,'↗')}${stat('Companies in your registry',data.sources.length,`${data.sources.filter(s=>s.last_success).length} successfully fetched`,'◎')}${stat('Application activity',data.history.length+data.autofill_history.length,'Saved, opened, or assisted','☷')}</div><div class="content-grid"><section class="panel"><div class="panel-head"><h2>${page==='saved'?'Your saved roles':'Discover your opportunities'}</h2><span>${jobs.length} relevant roles</span></div><div class="search-bar"><input class="search-input" id="job-search" type="search" aria-label="Search jobs" value="${esc(query)}" placeholder="⌕  Search a role, skill, or company"><select id="scope" aria-label="Job location"><option value="preferred" ${scope==='preferred'?'selected':''}>India + remote first</option><option value="all" ${scope==='all'?'selected':''}>All locations</option><option value="remote" ${scope==='remote'?'selected':''}>Remote first</option><option value="india" ${scope==='india'?'selected':''}>India</option><option value="world" ${scope==='world'?'selected':''}>Rest of world</option></select><select id="category" aria-label="Company stage"><option value="all">All company stages</option>${['YC startup','Startup','MNC','Unknown'].map(s=>`<option ${s===category?'selected':''}>${s}</option>`).join('')}</select></div>${laneSelector()}<div class="filter-pills"><button class="pill ${relevantOnly?'active':''}" data-action="relevant">${relevantOnly?'✓ ':''}Relevant to my resumes</button><button class="pill ${!onlyStrong&&!relevantOnly?'active':''}" data-action="all-matches">All collected roles</button><button class="pill ${onlyStrong?'active':''}" data-action="strong">Strong matches</button><span class="pill" style="cursor:default">↗ Remote → India → worldwide</span></div><div id="job-results">${jobs.length?jobs.map(jobCard).join(''):emptyJobs()}</div></section><aside class="right-column">${priorityPanel()}${coveragePanel()}${resumePanel()}</aside></div>`}
function emptyJobs(){return `<div class="empty"><div class="empty-icon">◎</div><h3>${query||scope!=='all'||onlyStrong?'A little adjustment might help.':page==='saved'?'A space for your shortlist.':'Let’s get your radar going.'}</h3><p>${data.jobs.length?'No roles match these filters. Try a broader role, location, or relevance threshold.':'No live jobs have been collected yet. Add your resume, start the collector, and see the exact source coverage. We won’t invent listings to fill the page.'}</p><button class="button" data-action="${data.jobs.length?'clear-filters':'collect'}">${data.jobs.length?'Clear filters':'Run collection now'} →</button><a class="button secondary" href="#sources">View source coverage</a></div>`}
function platformPanel(){const roles=(roleLanes().find(l=>l.enabled!==false)?.roles||data.profile.roles||'your target role').slice(0,200);return `<section class="panel platform-panel"><div class="panel-head"><div><span class="eyebrow">PUBLIC SOURCES + YOUR BROWSER</span><h2>Bring more job platforms into your search.</h2></div><button class="button secondary small" data-action="copy-roles">Copy target roles</button></div><p class="tiny">Search for <b>${esc(roles)}</b>. Public ATS feeds collect automatically. On YC and Naukri, the helper captures supported listings visible in tabs you open, then the matcher uses your role resumes.</p><div class="platform-grid"><article><b>Company ATS boards</b><span class="tag green">Automatic collection</span><p>Greenhouse, Lever, Ashby, SmartRecruiters and supported public career pages.</p></article><article><b>YC / Work at a Startup</b><span class="tag">Browser-assisted discovery</span><p>Open a search and sign in if required. Supported visible listings can enter your local matching queue.</p><a href="https://www.ycombinator.com/jobs" target="_blank" rel="noopener noreferrer">Open YC jobs ↗</a></article><article><b>Naukri</b><span class="tag">Browser-assisted discovery</span><p>Search in your signed-in browser. The helper captures supported visible listings; login and verification stay with you.</p><a href="https://www.naukri.com/" target="_blank" rel="noopener noreferrer">Open Naukri ↗</a></article></div><p class="tiny">Keep the updated Chrome helper enabled. This covers visible supported listings and forms, not every platform or every job. Capturing a listing is separate from submitting an application.</p></section>`}
function sourceView(){const failed=data.sources.filter(s=>s.error).length;return title('THE BIG PICTURE','A wider search. Clearer coverage.','An expandable registry of startup, YC, and multinational career sources.',`<div class="inline-actions"><button class="button secondary" data-action="import-sources">Import CSV ↑</button><button class="button" data-action="add-source">+ Add company</button></div>`)+disconnected()+platformPanel()+`<div class="notice">No platform can guarantee every company and job on the internet. The ${data.sources.length} registry entries are candidate sources, not verified partnerships. ${failed} currently report an error. JavaScript-only, login-gated, and blocked boards require separate connectors.</div><div class="stat-row">${stat('Registered companies',data.sources.length,'Add more at any time','◎')}${stat('Fetched at least once',data.sources.filter(s=>s.last_success).length,'Inspect latest status below','✓')}${stat('Need attention',failed,'Errors stay visible','!')}${stat('Source adapters',5,'Public feeds & structured pages','⌘')}</div><section class="panel"><div class="panel-head"><h2>Company registry</h2><button class="button secondary small" data-action="collect">${data.collecting?'Collecting…':'↻ Check all sources'}</button></div><div class="table-wrap"><table><thead><tr><th>COMPANY</th><th>CONNECTOR</th><th>STATUS</th><th>LAST SUCCESS</th><th>JOBS</th><th>ENABLED</th></tr></thead><tbody>${data.sources.map(s=>`<tr><td><b>${esc(s.company)}</b><small>${esc(s.category)}</small></td><td>${esc(s.kind)}<small>${esc(s.board)}</small></td><td><span class="source-status ${s.error?'failed':s.last_success?'':'pending'}">${s.error?'● Needs attention':s.last_success?'● Last fetch succeeded':'○ Unverified candidate'}</span>${s.error?`<small>${esc(s.error)}</small>`:''}</td><td>${timeAgo(s.last_success)}</td><td>${s.job_count||0}</td><td><input class="toggle" type="checkbox" data-source-id="${s.id}" ${s.enabled?'checked':''} aria-label="Enable ${esc(s.company)}"></td></tr>`).join('')||'<tr><td colspan="6">Connect the backend to load the registry.</td></tr>'}</tbody></table></div></section><div class="notice" style="margin-top:20px">Need a company that is missing? Add its Greenhouse, Lever, Ashby, or SmartRecruiters board ID, or a public HTTPS career page. The career-page adapter reads JobPosting structured data on up to 30 same-host pages, respects robots.txt, and can discover linked ATS boards. It cannot bypass login or CAPTCHA.</div><div class="inline-actions"><a class="button secondary" href="https://www.ycombinator.com/jobs" target="_blank" rel="noopener noreferrer">YC job directory ↗</a><a class="button secondary" href="https://www.ycombinator.com/companies" target="_blank" rel="noopener noreferrer">Find more YC companies ↗</a></div>`}
function applicationView(){return title('A LITTLE ORDER IN THE PROCESS','Your journey, kept in view.','Every saved role, opened application, and browser-helper attempt in one place.')+disconnected()+`<div class="notice">After one-time setup, the browser helper opens queued strong matches without a daily cap and autofills supported employer forms while Chrome and the local server are running. Autopilot advances supported steps and can click Submit. It records a confirmed submission only after an explicit employer confirmation. Unknown questions, logins, and CAPTCHAs remain in history.</div><section class="panel"><div class="panel-head"><h2>Your application history</h2><button class="button secondary small" data-action="export-history">Export history ↓</button></div>${data.history.length?`<div class="table-wrap"><table><thead><tr><th>ROLE & COMPANY</th><th>STATUS</th><th>LAST ACTIVITY</th><th>APPLICATION</th></tr></thead><tbody>${data.history.map(h=>`<tr><td><b>${esc(h.title||'Role no longer in feed')}</b><small>${esc(h.company)}</small></td><td><select data-history-id="${esc(h.job_id)}" aria-label="Application status">${!['saved','opened','applied','dismissed'].includes(h.status)?`<option selected disabled>${statusLabel(h.status)}</option>`:''}${['saved','opened','applied','dismissed'].map(s=>`<option value="${s}" ${h.status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></td><td>${timeAgo(h.updated)}</td><td>${h.apply_url?`<a href="${esc(h.apply_url)}" target="_blank" rel="noopener noreferrer">Open job ↗</a>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><div class="empty-icon">☷</div><h3>Your story is just getting started.</h3><p>Save or open a collected role and it will appear here. Autofill attempts are recorded below.</p><a class="button" href="#matches">Explore matches →</a></div>'}</section><h2 class="section-title">Browser-helper activity</h2><section class="panel">${data.autofill_history.length?`<div class="table-wrap"><table><thead><tr><th>APPLICATION</th><th>RESULT</th><th>DETAILS</th><th>WHEN</th></tr></thead><tbody>${data.autofill_history.map(h=>{let d={};try{d=typeof h.details==='string'?JSON.parse(h.details):h.details}catch{}return `<tr><td><b>${esc(h.title)}</b><small><a href="${esc(h.url)}" target="_blank" rel="noopener noreferrer">Open application ↗</a></small></td><td>${statusLabel(h.status)}</td><td>${(d.filled||[]).length} fields filled<small>${esc((d.remaining||[]).join(', ')||'Review all answers before submitting.')}</small></td><td>${timeAgo(h.created)}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty"><p>No helper activity has synced yet. The helper keeps a local history if the dashboard server is offline.</p><a href="#settings" class="button secondary">Set up the autofill helper →</a></div>'}</section>`}
function notificationView(){return title('GOOD THINGS, WHEN THEY APPEAR','Your opportunity inbox.','Job titles, direct application links, and why they reached your shortlist.',`<button class="button secondary" data-action="read-notifications">Mark all as read</button>`)+disconnected()+`<div class="notice">Matches at or above your relevance threshold (${data.settings.threshold}/100) appear here after a collection or resume update. Browser alerts require permission and an open dashboard tab. This version does not send email, SMS, or mobile push while the browser is closed.</div><section class="panel">${data.notifications.length?data.notifications.map(n=>`<article class="notification ${n.seen?'':'unread'}"><span class="company-logo">↗</span><div><h3>${esc(n.title)}</h3><p>Relevance ${n.score}/100 · ${timeAgo(n.created)}</p><span class="tiny">Check the full description and eligibility before applying.</span></div><button class="button secondary small" data-action="notification-open" data-id="${n.id}">View job ↗</button></article>`).join(''):'<div class="empty"><div class="empty-icon">♧</div><h3>A little quiet, for now.</h3><p>Once your resume and job sources are connected, suitable roles will appear here with their application links.</p><button class="button secondary" data-action="resume">Add or update your resume ↑</button></div>'}</section>`}
function automationPanel(){const a=data.automation_state||{},helper=Boolean(a.helper_connected),hasResume=Boolean(data.profile.resume||roleLanes().some(l=>l.enabled!==false&&l.resume)),enabled=a.enabled??data.settings.autopilot_enabled!==false;return `<section class="panel agent-overview"><div class="panel-head"><div><span class="eyebrow">YOUR LOCAL APPLICATION TEAM</span><h2>${!enabled?'Application agent is paused':helper?'Browser helper connected':'Connect the browser helper to apply'}</h2></div><button class="button" data-action="run-agent" ${!live()?'disabled':''}>Run agent now →</button></div><div class="agent-flow">${[['1','Match','Choose the best enabled resume for each eligible job'],['2','Prepare','Fill your saved facts and reusable answers'],['3','Apply','Advance supported forms and record the outcome']].map(([n,t,d])=>`<div><span>${n}</span><b>${t}</b><small>${d}</small></div>`).join('')}</div><div class="agent-metrics"><div><b>${Number(a.queued||0)}</b><span>Eligible in queue</span></div><div><b>${Number(a.blocked||0)}</b><span>Need an answer or login</span></div><div><b>${Number(a.submitted||0)}</b><span>Employer confirmations</span></div><div><b>${helper?'Connected':'Offline'}</b><span>Browser helper${a.last_seen?' · '+timeAgo(a.last_seen):''}</span></div></div><div class="agent-readiness"><span class="${hasResume?'ready':''}">${hasResume?'✓':'○'} Resume configured</span><span class="${helper?'ready':''}">${helper?'✓':'○'} Chrome helper connected</span><span class="${enabled?'ready':''}">${enabled?'✓':'○'} Autopilot enabled</span></div><p class="tiny">The collector and matcher run locally. Applications run in your browser using your signed-in sessions. Missing factual answers, employer login and interactive CAPTCHA are paused for you; they are not fabricated or bypassed.</p><div class="inline-actions"><a class="button secondary small" href="#lanes">Manage role resumes</a><a class="button secondary small" href="#questions">Answer exceptions once (${(data.questions||[]).filter(q=>!q.answered).length})</a><a class="button secondary small" href="#applications">View agent activity</a></div></section>`}
function lanesView(){const lanes=roleLanes();return title('ONE SEARCH. SEVERAL DIRECTIONS.','A resume for every role.','Keep your application facts shared, and match each opportunity against the right experience.',`<button class="button" data-action="add-lane">+ Add role resume</button>`)+disconnected()+`<div class="notice">Each enabled lane has its own target roles, resume and experience level. The matcher chooses the best eligible lane for a job, and the application helper uses that resume. Paused lanes are excluded from automatic matching.</div><div class="lane-grid">${lanes.length?lanes.map(l=>`<article class="panel lane-card"><div class="lane-card-top"><span class="lane-icon">◈</span><span class="tag ${l.enabled===false?'':'green'}">${l.enabled===false?'Paused':'Matching enabled'}</span></div><h2>${esc(l.name)}</h2><p>${esc(l.roles||'Target roles inferred from resume')}</p><div class="lane-file">▤ ${esc(l.resume_filename||l.resume_file?.name||'Pasted resume text')}</div><div class="lane-summary"><span>${Number(l.years||0)} years experience</span><span>${(l.skills||[]).length} skill keywords</span></div><div class="job-skills">${(l.skills||[]).slice(0,8).map(skill=>`<span class="skill">${esc(skill)}</span>`).join('')}</div><div class="inline-actions"><button class="button secondary small" data-action="edit-lane" data-id="${esc(l.id)}">Edit lane</button><button class="text-danger" data-action="delete-lane" data-id="${esc(l.id)}">Remove</button></div></article>`).join(''):`<section class="panel empty"><div class="empty-icon">▤</div><h3>Start with one direction.</h3><p>Add separate resumes for backend, frontend, data or other roles you actually want. Your existing profile remains the fallback until you add a lane.</p><button class="button" data-action="add-lane">Add your first role resume →</button></section>`}</div><section class="panel shared-profile"><div><h3>One shared application profile</h3><p class="tiny">Contact details, employment, education and answers are reused across lanes. You do not need to enter them for each resume.</p></div><button class="button secondary" data-action="resume">Edit shared facts →</button></section>`}
function laneModal(id){laneUpload=null;const l=roleLanes().find(x=>x.id===id)||{enabled:true,years:data.profile.years||0};openModal(id?'Edit this role lane.':'Give this resume a direction.',`${disconnected()}<form id="lane-form">${id?`<input type="hidden" name="id" value="${esc(id)}">`:''}<div class="form-grid"><div class="field"><label for="lane-name">Lane name</label><input id="lane-name" name="name" required maxlength="100" value="${esc(l.name)}" placeholder="e.g. Backend engineering"></div><div class="field"><label for="lane-roles">Target roles</label><input id="lane-roles" name="roles" required maxlength="500" value="${esc(l.roles)}" placeholder="Backend engineer, Python developer"></div><div class="field"><label for="lane-years">Relevant years of experience</label><input id="lane-years" name="years" type="number" min="0" max="60" step="1" required value="${esc(l.years)}"></div><div class="field"><label for="lane-location">Preferred locations</label><input id="lane-location" name="location" maxlength="300" value="${esc(l.location||data.profile.location||'India')}"></div></div><div class="upload"><label for="lane-resume-file">↑ Upload this role’s resume</label><input id="lane-resume-file" type="file" accept=".pdf,.docx,.txt,.md"><small>PDF, DOCX, TXT · Up to 5 MB · Processed locally</small></div><p class="tiny" id="lane-upload-status">${esc(l.resume_filename||l.resume_file?.name||'Upload a file or paste resume text below.')}</p><div class="field"><label for="lane-resume">Resume text</label><textarea id="lane-resume" name="resume" rows="10" minlength="40" maxlength="100000" required>${esc(l.resume)}</textarea><small>Keep this resume focused on the target roles. Saving unchanged text retains its current attachment.</small></div><label class="checkbox-label"><input id="lane-enabled" type="checkbox" ${l.enabled!==false?'checked':''}> Include this lane in matching and applications</label><div class="modal-actions"><button class="button" type="submit">Save role lane →</button><button class="button secondary" type="button" data-action="close">Cancel</button></div></form>`)}
function settingsView(){return title('YOUR SEARCH, IN MOTION','Put the repetitive parts to work.','One profile for your facts. A resume for each role. One queue that resumes when answers are learned.')+disconnected()+automationPanel()+`<div class="settings-grid"><section class="panel"><h2>Twice-daily collection</h2><p>The background collector checks due company sources every 12 hours while the server is running. It works when this tab is closed, provided the computer stays awake and the server process stays alive.</p><div class="health-row"><span>Collector</span><b>${data.collecting?'Running now':live()?'Ready':'Not connected'}</b></div><div class="health-row"><span>Last heartbeat</span><b>${timeAgo(data.settings.heartbeat)}</b></div><form id="settings-form"><div class="field"><label><input class="toggle" type="checkbox" id="autopilot-enabled" ${data.settings.autopilot_enabled!==false?'checked':''}> Enable application autopilot</label><small>Process qualifying matches without a daily cap while Chrome and the server run.</small></div><div class="field"><label><input class="toggle" type="checkbox" id="auto-submit" ${data.settings.auto_submit!==false?'checked':''}> Automatically submit complete queued applications</label><small>Missing answers and employer verification steps pause the attempt. Disable this for fill-only operation.</small></div><div class="field"><label><input class="toggle" type="checkbox" id="scheduler-enabled" ${data.settings.scheduler_enabled?'checked':''}> Enable twice-daily collection</label></div><div class="field"><label for="threshold">Notification relevance threshold (0–100)</label><input id="threshold" type="number" min="0" max="100" value="${data.settings.threshold}"></div><button class="button" type="submit">Save automation settings</button></form><div class="divider"></div><button class="button secondary" data-action="collect">↻ Run a collection now</button><p class="tiny" style="margin:15px 0 0">For continuous use, run <code style="display:inline;padding:2px">python3 server.py</code> under a process supervisor. A systemd user-service template is included. Cloud scheduling is not active.</p></section><section class="panel"><h2>Browser application agent</h2><div class="steps"><div><b>Add your resume and profile</b><p>Save your name, contact details, links, and resume once. They are used as provided.</p></div><div><b>Install the local browser helper</b><p>Download the extension ZIP, extract it, then choose Load unpacked in Chrome’s Extensions developer mode.</p></div><div><b>Open this dashboard once</b><p>The helper connects directly to your local dashboard, keeps your profile current, and refreshes its session after a server restart. Manual profile export remains available as a fallback.</p></div><div><b>Let supported applications open automatically</b><p>While Chrome and the local server are running, the helper checks matches every minute and opens queued strong matches in background tabs, with no daily cap. It fills queued employer forms, advances supported steps, and submits when all required answers are available. Add recurring answers once in your profile. Each blocked or completed attempt is recorded.</p></div></div><div class="inline-actions"><a class="button secondary" href="/extension.zip" download>Download helper ↓</a><button class="button" data-action="export-profile">Export helper profile ↓</button></div><p class="tiny" style="margin-top:17px">Supports common fields and resume-file inputs. Custom widgets, nested cross-origin frames, and some file controls may require manual completion. Automatic submission applies to queued matches when required answers and validations are complete; employer confirmation is tracked separately.</p></section><section class="panel"><h2>Notifications & privacy</h2><p>All processing is local. No resume text is sent to an AI provider. Matching checks each enabled role lane, its resume skills, role family, seniority, and location. Unrelated roles are excluded from the application queue.</p><button class="button secondary" data-action="enable-notifications">Enable browser alerts</button><p class="tiny" style="margin-top:15px">Permission is requested once by your browser. An open tab is required. Email/SMS/push providers are not configured.</p><div class="divider"></div><button class="button danger" data-action="delete-profile">Delete saved resume & profile</button><p class="tiny" style="margin-top:12px">Also remove the imported profile from the browser helper. Existing application history is retained until you delete the local database.</p></section><section class="panel"><h2>Run it locally</h2><p>Python 3.11+ is required. There are no Python packages to install. PDF reading uses the optional pdftotext utility; DOCX and plain text work without it.</p><code>cd /home/ved-kumar/role-radar\npython3 server.py\n# Open http://127.0.0.1:8877\n\n# One collection without starting the website:\npython3 server.py --once</code><p class="tiny">No paid API is required for the included public-source adapters. Large-scale crawling, hosted infrastructure, discovery services, cloud browsers, and external alerts have separate operational costs.</p><h3>What broad coverage needs</h3><p>Add/import more company boards. Workday, LinkedIn, Indeed, and other gated or dynamic systems need dedicated authorised connectors; they are not silently counted as covered.</p></section></div><h2 class="section-title">Recent collection runs</h2><section class="panel"><div class="table-wrap"><table><thead><tr><th>STARTED</th><th>STATUS</th><th>SOURCES</th><th>NEW JOBS</th><th>ERRORS</th></tr></thead><tbody>${data.runs.map(r=>`<tr><td>${timeAgo(r.started)}</td><td>${esc(r.status)}</td><td>${r.sources}</td><td>${r.new_jobs}</td><td>${r.errors}</td></tr>`).join('')||'<tr><td colspan="5">No runs yet.</td></tr>'}</tbody></table></div></section>`}
function render(){page=location.hash.slice(1)||'matches';if(!labels[page])page='matches';$('#crumb').textContent=labels[page];document.title=`${labels[page]} — Role Radar`;document.querySelectorAll('#navigation a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#main').innerHTML=({matches,saved:matches,sources:sourceView,applications:applicationView,questions:questionsView,lanes:lanesView,notifications:notificationView,settings:settingsView}[page])();updateChrome()}
function openModal(title,body){lastFocus=document.activeElement;$('#modal').innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="modal-close" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div></section>`;$('#modal').hidden=false;document.body.style.overflow='hidden';$('#modal').querySelector('input,button,select,textarea')?.focus()}
function closeModal(){$('#modal').hidden=true;document.body.style.overflow='';lastFocus?.focus()}
function answerRow(a={}){return `<div class="form-grid" data-answer-row data-section="${esc(a.section||'')}" data-index="${Number(a.index||0)}"><div class="field"><label>Exact application question</label><input data-question value="${esc(a.question||'')}" placeholder="Copy a recurring question from history"></div><div class="field"><label>Your saved answer</label><input data-answer value="${esc(a.answer??'')}" placeholder="For example: Yes, No, or your own text"><button type="button" class="button ghost" data-action="remove-answer">Remove</button></div></div>`}
const applicationFacts=[
 ['professional_summary','Professional summary from your resume','textarea'],['phone_country_code','Phone calling code (for example +91)','text'],['available_start_date','Earliest available start date','date'],['notice_period_days','Notice period in days','number'],['expected_salary','Expected salary amount','number'],['salary_currency','Salary currency (for example INR)','text'],['salary_period','Salary period','salary'],['work_authorization_country','Country your work authorisation answer applies to','text'],['authorized_to_work','Legally authorised to work in that country','yesno'],['sponsorship_now','Require employer sponsorship now','yesno'],['sponsorship_future','Require employer sponsorship in future','yesno'],['willing_relocate','Willing to relocate','yesno'],['willing_travel','Willing to travel for work','yesno'],['employment_type','Preferred employment type','text']
];
function factsFields(p){return applicationFacts.map(([key,label,type])=>`<div class="field ${type==='textarea'?'full':''}"><label for="p-${key}">${label}</label>${['yesno','salary'].includes(type)?`<select id="p-${key}" name="${key}"><option value="">Not provided</option>${(type==='yesno'?[['yes','Yes'],['no','No']]:[['annual','Annual'],['monthly','Monthly'],['hourly','Hourly']]).map(([value,text])=>`<option value="${value}" ${p[key]===value?'selected':''}>${text}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="p-${key}" name="${key}" rows="4">${esc(p[key])}</textarea>`:`<input id="p-${key}" name="${key}" type="${type}" value="${esc(p[key])}" ${type==='number'?'min="0"':''}>`}</div>`).join('')}
function recordRow(kind,r={}){const fields=kind==='work'?[['company','Employer'],['title','Job title'],['location','Location'],['start_date','Start date'],['end_date','End date'],['description','Responsibilities / achievements']]:[['school','School / university'],['degree','Degree / qualification'],['field','Field of study'],['start_date','Start date'],['end_date','Graduation / end date'],['grade','Grade / GPA (optional)']];return `<div class="record-card" data-record-kind="${kind}"><div class="form-grid">${fields.map(([key,label])=>`<div class="field ${key==='description'?'full':''}"><label>${label}</label>${key==='description'?`<textarea data-record-field="${key}" rows="3">${esc(r[key])}</textarea>`:`<input data-record-field="${key}" type="${key.endsWith('_date')?'date':'text'}" value="${esc(r[key])}">`}</div>`).join('')}</div><label class="tiny"><input class="toggle" data-record-current type="checkbox" ${r.current?'checked':''}> ${kind==='work'?'I currently work here':'I currently study here'}</label><button type="button" class="button ghost" data-action="remove-record">Remove entry</button></div>`}
function profileRecords(){const read=kind=>[...document.querySelectorAll(`[data-record-kind="${kind}"]`)].map(row=>({...Object.fromEntries([...row.querySelectorAll('[data-record-field]')].map(input=>[input.dataset.recordField,input.value])),current:row.querySelector('[data-record-current]').checked}));return {work_history:read('work'),education:read('education')}}
function questionsView(){const questions=[...(data.questions||[])].sort((a,b)=>Number(a.answered)-Number(b.answered));return title('FILL IT ONCE, REUSE IT','One answer. Fewer interruptions.','Questions collected from actual applications. Save an answer here and matching blocked applications can resume.')+disconnected()+`<div class="notice">The agent learns the answers you explicitly save here and reuses compatible questions across future applications. Already answered questions remain editable below. Only answer-dependent exceptions appear here; it will not invent facts about your eligibility, experience, or preferences. CAPTCHAs stay on their employer tabs for you to complete.</div><section class="panel">${questions.length?questions.map(q=>{let options=[];try{options=JSON.parse(q.options||'[]')}catch{}let answer='';try{answer=q.answer?JSON.parse(q.answer):''}catch{}return `<article class="question-card"><form data-question-form="${q.id}"><div><span class="eyebrow">${q.section?esc(q.section)+' entry '+(Number(q.record_index)+1):'Application question'} · encountered ${q.occurrences} times</span><div class="question-context"><span class="tag ${q.answered?'green':''}">${q.answered?'Learned answer':'Needs your answer'}</span>${q.lane_name?`<span class="tag">${esc(q.lane_name)}</span>`:''}</div><h3>${esc(q.question)}</h3>${options.length?`<select name="answer" required aria-label="Your answer"><option value="">Choose your answer</option>${options.map(option=>`<option value="${esc(option)}" ${String(answer)===option?'selected':''}>${esc(option)}</option>`).join('')}</select>`:`<textarea name="answer" rows="3" required placeholder="Your factual answer, saved for reuse" aria-label="Your answer">${esc(answer)}</textarea>`}<div class="inline-actions" style="margin-top:13px"><button class="button small" type="submit">${q.answered?'Update saved answer':'Save answer & resume applications'}</button><a class="button secondary small" href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">Original application ↗</a></div></div></form></article>`}).join(''):'<div class="empty"><div class="empty-icon">?</div><h3>No unanswered fields collected yet.</h3><p>When an application asks for information outside your profile, its exact question and available options appear here. Save it once instead of typing it repeatedly on employer websites.</p><button class="button" data-action="resume">Complete application profile →</button></div>'}</section>`}
function resumeModal(){upload=null;const p=data.profile;openModal('A little context about you.',`${disconnected()}<form id="profile-form"><div class="upload"><label for="resume-file">↑ &nbsp; Upload your resume</label><input id="resume-file" type="file" accept=".pdf,.docx,.txt,.md"><small>PDF, DOCX, TXT · Up to 5 MB · Processed locally</small></div><p class="tiny" id="upload-status" style="margin:10px 0 0">Upload a file or paste your resume below.</p><div class="form-grid">${[['name','Full name',p.name,'text'],['email','Email',p.email,'email'],['phone','Phone',p.phone,'tel'],['location','Preferred locations',p.location||'India','text'],['roles','Target role keywords',p.roles,'text'],['years','Years of experience',p.years??0,'number'],['linkedin','LinkedIn URL',p.linkedin,'url'],['website','Portfolio / website',p.website,'url'],['github','GitHub URL',p.github,'url'],['current_city','Current city',p.current_city,'text'],['country','Country of residence',p.country,'text'],['state','State / province',p.state,'text'],['postal_code','Postal code',p.postal_code,'text'],['street','Street address',p.street,'text'],['current_company','Current employer',p.current_company,'text'],['current_title','Current job title',p.current_title,'text']].map(([key,label,value,type])=>`<div class="field"><label for="p-${key}">${label}</label><input id="p-${key}" name="${key}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" max="60"':''} ${key==='name'?'autocomplete="name"':''}></div>`).join('')}<div class="field full"><label for="p-resume">Resume text</label><textarea id="p-resume" name="resume" rows="8" ${roleLanes().some(l=>l.enabled!==false&&l.resume?.length>=40)?'':'minlength="40" required'} maxlength="100000" placeholder="Paste your experience, skills, and education here…">${esc(p.resume)}</textarea><small>${roleLanes().some(l=>l.enabled!==false&&l.resume?.length>=40)?'Optional shared resume: enabled role lanes provide their own matching text and attachments. Keep this profile for shared contact details and answers.':'Add a shared resume here or create focused resumes under Resumes & role lanes. Priority remains remote → India → worldwide.'}</small></div></div><h3>Application facts and preferences</h3><p class="tiny">Provide these once. Blank means unknown; the agent will never assume work authorisation or sponsorship answers.</p><div class="form-grid">${factsFields(p)}</div><h3>Experience by skill</h3><p class="tiny">Optional: enter actual years per skill, one per line, such as Python: 3. Total experience is not used to guess skill-specific experience.</p><textarea id="skill-years" rows="4">${esc(Object.entries(p.skill_years||{}).map(([skill,years])=>skill+': '+years).join('\n'))}</textarea><h3>Work history</h3><div id="work-records">${(p.work_history||[]).map(r=>recordRow('work',r)).join('')}</div><button class="button secondary small" type="button" data-action="add-work">+ Add employment</button><h3 style="margin-top:25px">Education</h3><div id="education-records">${(p.education||[]).map(r=>recordRow('education',r)).join('')}</div><button class="button secondary small" type="button" data-action="add-education">+ Add education</button><h3>Reusable application answers</h3><p class="tiny">Save recurring questions and your factual answers once. The helper can reuse supported equivalent questions with the same context and options. Job-specific prose and unknown legal or eligibility facts are never invented.</p><div id="answer-bank">${(p.answers||[]).map(answerRow).join('')}</div><button class="button secondary small" type="button" data-action="add-answer">+ Add an answer</button><div class="field"><label for="p-cover-letter">Reusable cover letter (optional, your own text)</label><textarea id="p-cover-letter" name="cover_letter" rows="4">${esc(p.cover_letter)}</textarea></div><div class="notice">Matching is a transparent heuristic, not a guarantee of fit. Known application forms use the fields you save here. Unprovided answers, sensitive demographic questions, and legal attestations are never guessed.</div><div class="modal-actions"><button class="button" type="submit">Save profile & find my matches →</button><button class="button secondary" type="button" data-action="close">Cancel</button></div></form>`)}
function sourceModal(){openModal('Bring another company into view.',`<form id="source-form"><div class="field"><label for="s-company">Company name</label><input id="s-company" name="company" required maxlength="100"></div><div class="form-grid"><div class="field"><label for="s-kind">Source type</label><select id="s-kind" name="kind">${['greenhouse','lever','ashby','smartrecruiters','career_page'].map(s=>`<option>${s}</option>`).join('')}</select></div><div class="field"><label for="s-category">Company category</label><select id="s-category" name="category">${['Unknown','YC startup','Startup','MNC'].map(s=>`<option>${s}</option>`).join('')}</select></div></div><div class="field"><label for="s-board">ATS board ID or public career-page URL</label><input id="s-board" name="board" required placeholder="e.g. stripe — or an HTTPS URL for career_page"></div><p class="tiny">For Greenhouse, Lever, Ashby, or SmartRecruiters, enter the company’s board identifier. For a company website, choose career_page and provide its HTTPS career URL.</p><button class="button" type="submit">Add company source →</button></form>`)}
function detailModal(id){const original=data.jobs.find(j=>j.id===id);if(!original)return;const j={...original,match:laneMatch(original)||original.match};openModal(esc(j.title),`<p class="tiny">${esc(j.company)} · ${esc(j.location)} · ${esc(j.employment)}</p>${j.match.lane_name?`<p class="job-lane">Preview: ${esc(j.match.lane_name)} · Autopilot choice: ${esc(original.match.lane_name||'Best enabled resume')}</p>`:''}<div class="match-reasons"><strong>${j.match.score===null?'Upload your resume for a relevance score':`Relevance: ${j.match.score}/100`}</strong><ul>${j.match.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>${j.match.matched.length?`<p>Skill overlap: ${esc(j.match.matched.join(', '))}</p>`:''}${j.match.missing.length?`<p>Other skills mentioned: ${esc(j.match.missing.join(', '))}</p>`:''}</div><p class="tiny" style="margin-top:18px">${j.match.warnings.map(esc).join('<br>')}</p><h3>About the role</h3><div class="job-description">${esc(j.description)}</div><div class="notice" style="margin-top:20px">${demo?'This is a fictional preview role, not an available job.':'The browser helper can open strong matches automatically and fills supported fields after setup. Otherwise, use this direct employer application link and complete the remaining fields. Queued matches can submit automatically under your autopilot settings. Missing answers appear in history.'}</div><div class="modal-actions"><button class="button" data-action="apply" data-id="${j.id}" ${demo?'disabled':''}>Open application & autofill ↗</button><button class="button secondary" data-action="save" data-id="${j.id}">Save for later ▱</button></div>`)}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
async function action(name,target){try{
if(name==='copy-roles'){const roles=roleLanes().find(l=>l.enabled!==false)?.roles||data.profile.roles||'';if(!roles)throw Error('Add your target roles in a resume lane first.');if(!navigator.clipboard)throw Error('Clipboard unavailable. Your target roles are shown above.');await navigator.clipboard.writeText(roles);toast('Target roles copied. Paste them into the platform search.');return}if(name==='run-agent'){const result=await api('/api/automation/run',{});window.postMessage({type:'role-radar-run'},location.origin);await refresh(true);toast(result.message||'Queue refreshed. Connected browser helpers can pick up eligible jobs.');return}if(name==='add-lane')return laneModal();if(name==='edit-lane')return laneModal(target.dataset.id);if(name==='delete-lane'){if(!confirm('Remove this resume lane? Other resumes, shared profile facts and application history are kept.'))return;await api('/api/delete-lane',{id:target.dataset.id});if(selectedLane===target.dataset.id)selectedLane='all';await refresh(true);toast('Resume lane removed.');return}if(name==='add-work'){$('#work-records').insertAdjacentHTML('beforeend',recordRow('work'));return}if(name==='add-education'){$('#education-records').insertAdjacentHTML('beforeend',recordRow('education'));return}if(name==='remove-record'){target.closest('[data-record-kind]').remove();return}if(name==='add-answer'){$('#answer-bank').insertAdjacentHTML('beforeend',answerRow());return}if(name==='remove-answer'){target.closest('[data-answer-row]').remove();return}if(name==='resume')return resumeModal();if(name==='close')return closeModal();if(name==='notifications'){location.hash='notifications';return}if(name==='detail')return detailModal(target.dataset.id);
if(name==='collect'){await api('/api/collect',{});pending=true;toast('Collection started. Source results and failures will appear in coverage.');setTimeout(()=>refresh(true),1200);return}
if(name==='save'){const id=target.dataset.id,already=data.history.some(h=>h.job_id===id&&h.status==='saved');await api('/api/application',{job_id:id,status:already?'dismissed':'saved'});await refresh(true);toast(already?'Removed from saved jobs.':'Saved to your shortlist.');return}
if(name==='apply'){const j=data.jobs.find(j=>j.id===target.dataset.id);if(!j||demo)return;const opened=window.open(j.apply_url,'_blank','noopener,noreferrer');await api('/api/application',{job_id:j.id,status:'opened'});closeModal();await refresh(true);toast('Application opened. Queued matches can fill, advance, and submit under your saved autopilot policy.');return}
if(name==='notification-open'){const n=data.notifications.find(n=>n.id==target.dataset.id);if(n&&!demo)window.open(n.url,'_blank','noopener,noreferrer');return}
if(name==='relevant'){relevantOnly=!relevantOnly;render();return}if(name==='all-matches'){onlyStrong=false;relevantOnly=false;render();return}if(name==='strong'){onlyStrong=true;render();return}if(name==='clear-filters'){query='';scope='preferred';category='all';onlyStrong=false;relevantOnly=true;selectedLane='all';render();return}
if(name==='add-source')return sourceModal();
if(name==='import-sources'){openModal('Grow your company coverage.',`<p class="tiny">Import a UTF-8 CSV with the columns <b>company,kind,board,category</b>. Supported kinds: greenhouse, lever, ashby, smartrecruiters, career_page. Categories: YC startup, Startup, MNC, Unknown.</p><input id="source-csv" type="file" accept=".csv" aria-label="Company source CSV"><p class="tiny" style="margin-top:16px">Example row: <code>Example,greenhouse,example,Startup</code>. Every row is validated before any are saved.</p>`);return}
if(name==='export-profile'){if(!data.profile.resume)throw Error('Save your resume and profile first.');const r=await fetch('/api/export-profile');if(!r.ok)throw Error('Connect the local server first.');download('role-radar-private-profile.json',await r.json());toast('Export contains private resume data. Import it into the helper, then remove the download if no longer needed.');return}
if(name==='export-history')return download('role-radar-history.json',{applications:data.history,autofill:data.autofill_history});
if(name==='enable-notifications'){if(!('Notification'in window))throw Error('This browser does not support notifications.');notificationEnabled=(await Notification.requestPermission())==='granted';toast(notificationEnabled?'Browser alerts enabled while this tab remains open.':'Browser permission was not granted. In-app notifications still work.');return}
if(name==='read-notifications'){await api('/api/read-notifications',{});await refresh(true);return}
if(name==='delete-profile'){if(!confirm('Delete the locally saved resume and profile? Also clear the imported profile in your browser helper.'))return;await api('/api/delete-profile',{});await refresh(true);toast('Saved resume and profile deleted from the local server.');return}
}catch(e){toast(e.message)}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target)action(target.dataset.action,target);if(e.target===$('#modal'))closeModal()});
document.addEventListener('input',e=>{if(e.target.id==='job-search'){query=e.target.value;$('#job-results').innerHTML=filteredJobs().map(jobCard).join('')||emptyJobs()}});
document.addEventListener('change',async e=>{const t=e.target;try{if(t.id==='match-lane'){selectedLane=t.value;render()}if(t.id==='scope'){scope=t.value;render()}if(t.id==='category'){category=t.value;render()}if(t.dataset.sourceId){await api('/api/toggle-source',{id:t.dataset.sourceId,enabled:t.checked});await refresh(true)}if(t.dataset.historyId){await api('/api/application',{job_id:t.dataset.historyId,status:t.value});await refresh(true)}if(t.id==='lane-resume-file'){const file=t.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Choose a file no larger than 5 MB.');$('#lane-upload-status').textContent='Extracting resume locally…';const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.slice(i,i+8192));const result=await api('/api/resume',{name:file.name,data:btoa(raw)});laneUpload=result.resume_file;if(!$('#lane-name').value)$('#lane-name').value=file.name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ').slice(0,100);$('#lane-resume').value=result.text;$('#lane-years').value=result.years;$('#lane-upload-status').textContent=`${file.name} · ${result.skills.length} detected skills. Review the extracted text before saving.`;return}if(t.id==='resume-file'){const file=t.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Choose a file no larger than 5 MB.');$('#upload-status').textContent='Reading resume locally…';const buffer=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<buffer.length;i+=8192)binary+=String.fromCharCode(...buffer.slice(i,i+8192));const result=await api('/api/resume',{name:file.name,data:btoa(binary)});upload=result.resume_file;for(const [key,value] of Object.entries(result.suggested_facts||{})){const input=$('#p-'+key);if(input&&!input.value)input.value=value}$('#p-resume').value=result.text;$('#p-years').value=result.years;const email=result.text.match(/[\w.+-]+@[\w.-]+\.[a-zA-Z]{2,}/);if(email&&!$('#p-email').value)$('#p-email').value=email[0];$('#upload-status').textContent=`${file.name} · ${result.skills.length} skill keywords detected. Check the extracted text before saving.`}if(t.id==='source-csv'){const csv=await t.files[0].text();const result=await api('/api/import-sources',{csv});closeModal();await refresh(true);toast(`${result.rows} validated company rows imported.`)}}catch(e){toast(e.message);if($('#upload-status'))$('#upload-status').textContent=e.message}});
document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='lane-form'){const value=Object.fromEntries(new FormData(e.target));value.years=Number(value.years);value.enabled=$('#lane-enabled').checked;if(laneUpload)value.resume_file=laneUpload;await api('/api/lane',value);closeModal();await refresh(true);toast('Role lane saved. Matches now use the resume best suited to each role.');return}if(e.target.dataset.questionForm){await api('/api/question-answer',{id:e.target.dataset.questionForm,answer:new FormData(e.target).get('answer')});await refresh(true);toast('Answer saved. The agent will reuse it and retry matching blocked forms.');return}if(e.target.id==='profile-form'){const value=Object.fromEntries(new FormData(e.target));Object.assign(value,profileRecords());value.skill_years={};for(const line of $('#skill-years').value.split('\n').filter(x=>x.trim())){const match=line.match(/^(.+):\s*(\d+(?:\.\d+)?)\s*$/);if(!match)throw new Error('Use skill: years for each experience entry.');value.skill_years[match[1].trim()]=Number(match[2])}value.answers=[...document.querySelectorAll('[data-answer-row]')].map(row=>({question:row.querySelector('[data-question]').value,answer:row.querySelector('[data-answer]').value,section:row.dataset.section||'',index:Number(row.dataset.index||0)}));if(upload)value.resume_file=upload;await api('/api/profile',value);closeModal();await refresh(true);toast('Profile saved. Matches and notifications have been recalculated.')}if(e.target.id==='source-form'){await api('/api/source',Object.fromEntries(new FormData(e.target)));closeModal();await refresh(true);toast('Company source added. It will be checked by the collector.')}if(e.target.id==='settings-form'){await api('/api/settings',{threshold:Number($('#threshold').value),scheduler_enabled:$('#scheduler-enabled').checked,auto_submit:$('#auto-submit').checked,autopilot_enabled:$('#autopilot-enabled').checked});await refresh(true);toast('Automation settings saved.')}}catch(e){toast(e.message)}});
document.addEventListener('keydown',e=>{if($('#modal').hidden)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const items=[...$('#modal').querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
$('#example-toggle').addEventListener('click',()=>{demo=!demo;if(demo){data={jobs:[],sources:[],profile:{name:'Alex',resume:'Illustrative profile only',skills:['python','react','sql'],roles:'Software engineer'},history:[],autofill_history:[],questions:[],notifications:[],runs:[],settings:{threshold:55,scheduler_enabled:false},mode:'demo'};const examples=[['Orbitworks','Full Stack Engineer','Remote · India',true,'YC startup',88,['react','python','sql']],['Juniper Labs','Backend Engineer','Remote · Europe',true,'Startup',82,['python','sql']],['Northstar Systems','Software Engineer II','Bengaluru, India',false,'MNC',79,['python','react']],['Cedar Studio','Product Engineer','Mumbai, India',false,'Startup',74,['react','sql']],['Atlas Collective','Platform Engineer','London, United Kingdom',false,'MNC',69,['python']]];data.jobs=examples.map((x,i)=>({id:'example-'+i,company:x[0],title:x[1],location:x[2],remote:x[3],category:x[4],priority:x[3]?0:x[2].includes('India')?1:2,employment:'Full-time',salary:'',description:'Fictional example for interface preview. A role involving product development, collaboration, and maintainable software. This is not an actual vacancy.',match:{score:x[5],matched:x[6],missing:['docker'],reasons:['Illustrative score; no real matching was performed.'],warnings:['Fictional role. Do not apply.']}}));render()}else{data={jobs:[],sources:[],profile:{},history:[],autofill_history:[],questions:[],notifications:[],runs:[],settings:{threshold:55},mode:'offline'};refresh(true)}});
window.addEventListener('hashchange',render);$('#main').innerHTML='<div class="loading">Getting your workspace ready…</div>';refresh(true);setInterval(()=>refresh(),30000);
